WITH valid_stores AS (SELECT * FROM stores WHERE NOT (region IS NULL OR opened_date >= '2025-05-01')), stores_stats AS (SELECT YEAR(opened_date) AS opened_year, ROUND((100 * SUM(CASE WHEN region = 'Central' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_central FROM valid_stores GROUP BY YEAR(opened_date)) SELECT opened_year, pct_central FROM stores_stats WHERE pct_central >= 44 ORDER BY opened_year, 2 LIMIT 20;
